let farmCameraZoom=null;
const farmSceneMap=farmMap;
farmMap=function(){const n=cityPlots().length,width=Math.max(760,Math.min(1500,Math.ceil(Math.sqrt(n+1))*235));return `<div class="farm-camera-viewport gesture-map" tabindex="0" aria-label="Карта хозяйства: перетаскивайте для перемещения, сведите или разведите два пальца для масштаба. Клавиши плюс, минус, стрелки; Home — показать всё."><div class="farm-camera-scene" style="width:${width}px">${farmSceneMap()}</div></div>`};
const farmCameraStates=new WeakMap();const savedFarmCamera=new Map();const cameraStateKey=()=>String(account?.id||'guest')+':'+selectedFarmCity();
function fitFarmCamera(){const v=document.querySelector('.farm-camera-viewport'),s=document.querySelector('.farm-camera-scene');if(!v||!s)return;let c=farmCameraStates.get(v);if(!c){c={x:0,y:0,k:1,pointers:new Map(),dragged:false,until:0,ready:false};const saved=savedFarmCamera.get(cameraStateKey());if(saved)Object.assign(c,saved,{ready:true});farmCameraStates.set(v,c);installFarmGestures(v,s,c)}const box=getComputedStyle(v),top=parseFloat(box.paddingTop)||0,bottom=parseFloat(box.paddingBottom)||0;const usableH=Math.max(100,v.clientHeight-top-bottom);c.fit=Math.max(.08,Math.min(1,(v.clientWidth-24)/s.offsetWidth,(usableH-12)/s.offsetHeight));if(!c.ready||farmCameraZoom===null){c.k=c.fit;c.x=(v.clientWidth-s.offsetWidth*c.k)/2;c.y=top+(usableH-s.offsetHeight*c.k)/2;c.ready=true}paintFarmCamera(v,s,c)}
function paintFarmCamera(v,s,c){const w=s.offsetWidth*c.k,h=s.offsetHeight*c.k;c.x=Math.min(v.clientWidth-45,Math.max(45-w,c.x));c.y=Math.min(v.clientHeight-100,Math.max(45-h,c.y));s.style.transform=`translate(${c.x}px,${c.y}px) scale(${c.k})`;v.dataset.scale=String(c.k);savedFarmCamera.set(cameraStateKey(),{x:c.x,y:c.y,k:c.k})}
function zoomFarmAt(v,s,c,next,x,y){const old=c.k;c.k=Math.max(Math.min(c.fit,.15),Math.min(2.5,next));const ratio=c.k/old;c.x=x-(x-c.x)*ratio;c.y=y-(y-c.y)*ratio;farmCameraZoom=c.k;paintFarmCamera(v,s,c)}
function installFarmGestures(v,s,c){const pos=e=>{const r=v.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};v.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const p=pos(e);c.pointers.set(e.pointerId,p);if(c.pointers.size===1){c.start=p;c.dragged=false}if(c.pointers.size>1){c.dragged=true;c.until=Date.now()+500}});v.addEventListener('pointermove',e=>{const before=c.pointers.get(e.pointerId);if(!before)return;const p=pos(e);if(c.pointers.size===1){if(!c.dragged&&Math.hypot(p.x-c.start.x,p.y-c.start.y)<7)return;c.dragged=true;c.x+=p.x-before.x;c.y+=p.y-before.y;farmCameraZoom=c.k;c.pointers.set(e.pointerId,p);paintFarmCamera(v,s,c)}else{const old=[...c.pointers.values()],oldMid={x:(old[0].x+old[1].x)/2,y:(old[0].y+old[1].y)/2},distance=Math.hypot(old[0].x-old[1].x,old[0].y-old[1].y);c.pointers.set(e.pointerId,p);const now=[...c.pointers.values()],mid={x:(now[0].x+now[1].x)/2,y:(now[0].y+now[1].y)/2},d=Math.hypot(now[0].x-now[1].x,now[0].y-now[1].y);if(distance>2)zoomFarmAt(v,s,c,c.k*d/distance,oldMid.x,oldMid.y);c.x+=mid.x-oldMid.x;c.y+=mid.y-oldMid.y;paintFarmCamera(v,s,c);c.dragged=true}if(c.dragged){v.setPointerCapture(e.pointerId);v.classList.add('is-dragging');e.preventDefault()}});const release=e=>{if(c.dragged)c.until=Date.now()+500;c.pointers.delete(e.pointerId);if(c.pointers.size===1)c.start=[...c.pointers.values()][0];if(!c.pointers.size)v.classList.remove('is-dragging');if(v.hasPointerCapture(e.pointerId))v.releasePointerCapture(e.pointerId)};v.addEventListener('pointerup',release);v.addEventListener('pointercancel',release);v.addEventListener('click',e=>{if(Date.now()<c.until){e.preventDefault();e.stopImmediatePropagation()}},true);v.addEventListener('dragstart',e=>e.preventDefault());v.addEventListener('wheel',e=>{e.preventDefault();const p=pos(e);zoomFarmAt(v,s,c,c.k*Math.exp(-Math.max(-100,Math.min(100,e.deltaY))*.003),p.x,p.y)},{passive:false});v.addEventListener('keydown',e=>{if(e.target!==v)return;if(['+','=','-','Home','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();else return;if(e.key==='Home'){farmCameraZoom=null;fitFarmCamera()}else if(['+','=','-'].includes(e.key))zoomFarmAt(v,s,c,c.k*(e.key==='-'?.85:1.15),v.clientWidth/2,v.clientHeight/2);else{c.x+=e.key==='ArrowLeft'?35:e.key==='ArrowRight'?-35:0;c.y+=e.key==='ArrowUp'?35:e.key==='ArrowDown'?-35:0;farmCameraZoom=c.k;paintFarmCamera(v,s,c)}})}
let farmCameraObserver;
const beforeCameraRender=render;render=function(){beforeCameraRender();farmCameraObserver?.disconnect();const viewport=document.querySelector('.farm-camera-viewport');if(viewport){fitFarmCamera();farmCameraObserver=new ResizeObserver(fitFarmCamera);farmCameraObserver.observe(viewport)}};
addEventListener('hashchange',()=>{farmCameraZoom=null;fitFarmCamera()});render();
